            a.gap(box,10);LinearLayout buttons=a.row();int complete=i.done?R.string.todo_undo:i.repeat!=0?R.string.todo_complete_once:R.string.todo_complete;buttons.addView(a.button(t(complete),false,()->mutate(m->{TodoModel.Item current=m.find(i.id);if(current==null)return;if(current.done)current.done=false;else{TodoModel.Occurrence occurrence=TodoModel.next(current,System.currentTimeMillis(),ZoneId.systemDefault());if(occurrence!=null)TodoModel.complete(current,occurrence.day);}current.updated=System.currentTimeMillis();})),new LinearLayout.LayoutParams(0,-2,1));
