        else{StringJoiner ranges=new StringJoiner(", ");DateTimeFormatter format=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");for(TodoModel.Slot s:i.slots){ZonedDateTime from=Instant.ofEpochMilli(TodoModel.at(day,s.from,ZoneId.systemDefault())).atZone(zone),to=Instant.ofEpochMilli(TodoModel.at(day,s.to,ZoneId.systemDefault())).atZone(zone);ranges.add(from.format(format)+"–"+(to.toLocalDate().equals(from.toLocalDate())?to.format(DateTimeFormatter.ofPattern("HH:mm")):to.format(format)));}value=ranges+" · "+zone.getId();}
